package android.os;import java.util.*;public class Handler {static class Event {Runnable r;long at;Event(Runnable r,long at){this.r=r;this.at=at;}}static List<Event> events=new ArrayList<>();public Handler(Looper l){}public void post(Runnable r){postDelayed(r,0);}public void postDelayed(Runnable r,long d){events.add(new Event(r,SystemClock.now+d));}public void removeCallbacks(Runnable r){events.removeIf(e->e.r==r);}public static void advance(long d){long target=SystemClock.now+d;while(true){Event best=null;for(Event e:events)if(e.at<=target&&(best==null||e.at<best.at))best=e;if(best==null)break;events.remove(best);SystemClock.now=best.at;best.r.run();}SystemClock.now=target;}public static void reset(){events.clear();SystemClock.now=0;}}
